actions.script:
def EntityCondition = org.moqui.entity.EntityCondition
def cf = ec.entity.conditionFactory
def ef = ec.entity.find("mantle.request.Request")
if (requestTypeEnumId) ef.condition("requestTypeEnumId", requestTypeEnumId)
if (rootWorkEffortId) ef.condition("requestId", EntityCondition.IN, ec.entity.find("mantle.request.RequestWorkEffort")
        .condition("workEffortId", rootWorkEffortId).selectField("requestId").list()*.requestId ?: ["_NONE_"])
if (request != null) ef.condition("requestId", EntityCondition.NOT_EQUAL, request.requestId)
for (String word in (term ? term.toString().trim().split(/\s+/).findAll { it } : []))
    ef.condition(cf.makeCondition(["requestId", "requestName"].collect {
        cf.makeCondition(it, EntityCondition.LIKE, "%" + word + "%").ignoreCase() }, EntityCondition.OR))
ef.orderBy(["-requestDate", "requestId"]).limit(20)
for (def req in ef.list()) outList.add([value:req.requestId, label:ec.resource.expand("RequestNameTemplate", "", req)])
ec.web.sendJsonResponse(outList)
